  function fcInventory(){if(!fc.loaded&&!fc.loading){queueMicrotask(()=>fcLoad());return fcHead('工厂 · 库存','物资管理','正在加载库存…')+fcBanner();}const inventory=fcIsOwner()?fc.valuation:fc.inventory,category=fc.inventoryCategory||'五金',isHardware=x=>(x.cost_category||'')==='五金'||x.category==='五金'||x.category==='特殊物资',items=inventory.filter(x=>category==='五金'?isHardware(x):!isHardware(x)),rows=items.map(x=>`<tr><td>${esc(x.material_code)}</td><td>${esc(x.material_name)}</td><td>${esc(x.spec||'—')}</td><td>${esc(x.unit)}</td><td>${x.quantity_on_hand}</td><td>${x.safety_stock}</td><td>${esc(x.stock_status)}</td>${fcIsOwner()?`<td>${fcMoney(x.inventory_value)}</td>`:''}</tr>`).join(''),heads=['编码','物资','规格','单位','库存','安全库存','状态',...(fcIsOwner()?['库存金额']:[])],tabs=['五金','辅料'].map(x=>`<button class="btn ${category===x?'primary':''}" data-action="fc-inventory-category" data-category="${x}">${x} <span class="fc-tab-count">${inventory.filter(v=>x==='五金'?isHardware(v):!isHardware(v)).length}</span></button>`).join('');return fcHead('工厂 · 库存','物资管理','五金可上传采购单并扫码匹配、去重后登记入库；辅料以手动添加和登记为主。',`<button class="btn" data-action="fc-refresh">刷新</button><button class="btn" data-action="fc-material-new">＋ 手动添加${category==='五金'?'五金':'辅料'}</button>${category==='五金'?'<button class="btn primary" data-action="fc-bulk-in-new">＋ 扫描 / 登记五金入库</button>':''}`)+fcBanner()+`<div class="fc-inline-actions fc-inventory-tabs">${tabs}</div>`+panel(category+'库存档案',`${items.length} 项`,fcTable(heads,rows));}
  function fcFixedCosts(){if(!fc.loaded&&!fc.loading){queueMicrotask(()=>fcLoad());return fcHead('FACTORY COSTS · 工厂','工厂固定费用','正在加载登记明细…')+fcBanner();}const month=fc.financeMonth||fcMonth(),rows=fc.fixed.filter(x=>fcDateVal(x.cost_month).slice(0,7)===month).map(x=>`<tr><td>${fcDateVal(x.cost_month).slice(0,7)}</td><td>${esc(x.category)}</td><td>${esc(x.item||'—')}</td><td>${fcMoney(x.amount)}${x.cost_mode==='annual'?`<small class="cell-sub">年度总额 ${fcMoney(x.annual_amount)}</small>`:''}</td><td>${esc(x.ownership||'工厂')} · ${x.cost_mode==='annual'?'按年分摊':x.cost_mode==='one_time'?'一次性':'按月'}</td><td>${esc(x.note||'')}</td></tr>`).join('');return fcHead('FACTORY COSTS · 工厂','固定费用登记','厂长可登记工厂公共费用并查看费用明细；利润和工资仍由老板查看。',`<button class="btn" data-action="fc-refresh">刷新</button><button class="btn primary" data-action="fc-fixed-new">＋ 登记固定费用</button>`)+fcBanner()+`<div class="fc-toolbar"><label>成本月份<input class="field" type="month" value="${month}" data-fc-fixed-month></label></div>`+panel('工厂固定费用明细',`${rows?fc.fixed.filter(x=>fcDateVal(x.cost_month).slice(0,7)===month).length:0} 项`,fcTable(['月份','类别','项目','金额','归属','备注'],rows));}
